using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

// --- Build the agent ---
var agent = new ChatClientBuilder()
    .UseOpenAIChatClient(modelId, apiKey)
    .BuildAIAgent(new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    });

// --- System prompt ---
var systemMessage = new ChatMessage(ChatRole.System, """
    You are a research assistant. When the user gives you a topic:

    1. Use the SearchWeb tool multiple times with different queries to gather information.
    2. Use the SaveNote tool to record key findings as you go.
    3. Use the GetNotes tool to review everything you've collected.
    4. Provide a well-structured summary with sections and source references.

    Be thorough — search at least 3 different queries before summarizing.
    """);

// --- Interactive loop ---
Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.WriteLine();

var session = await agent.CreateSessionAsync();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("You> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    var messages = new List<ChatMessage> { systemMessage, new(ChatRole.User, input) };

    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("\nAgent> ");
    Console.ResetColor();

    var runOptions = new ChatClientAgentRunOptions(new ChatOptions
    {
        MaxOutputTokens = 2048,
        Temperature = 0f,
    });

    await foreach (var update in agent.RunStreamingAsync(messages, session, runOptions))
    {
        Console.Write(update.Text);
    }

    Console.WriteLine("\n");
}

// --- Tool definitions ---
[Description("Tools for researching topics on the web and taking notes.")]
static class ResearchTools
{
    private static readonly HttpClient s_httpClient = new();
    private static readonly List<string> s_notes = [];

    [Description("Search the web for information on a query. Returns relevant search result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&format=json&srlimit=5&utf8=1";

            var response = await s_httpClient.GetStringAsync(url, cancellationToken);

            // Parse the JSON and extract snippets
            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var results = doc.RootElement.GetProperty("query").GetProperty("search");

            var snippets = new List<string>();
            foreach (var result in results.EnumerateArray())
            {
                var title = result.GetProperty("title").GetString();
                var snippet = result.GetProperty("snippet").GetString();
                // Strip HTML tags from snippet
                snippet = System.Text.RegularExpressions.Regex.Replace(snippet ?? "", "<.*?>", "");
                snippets.Add($"- **{title}**: {snippet}");
            }

            return snippets.Count > 0
                ? $"Search results for '{query}':\n{string.Join("\n", snippets)}"
                : $"No results found for '{query}'.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings during research.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        s_notes.Add(note);
        return $"Note #{s_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var formatted = s_notes.Select((n, i) => $"[{i + 1}] {n}");
        return $"Saved notes ({s_notes.Count}):\n{string.Join("\n", formatted)}";
    }
}

